export type MarkdownHeading = {
  /** Heading level, from 1 (top level) to 6. */
  depth: number
  /** Plain-text content of the heading with all inline formatting removed. */
  value: string
}

/** Matches an ATX heading: 1-6 leading hashes followed by at least one space and the content. */
const ATX_HEADING = /^(#{1,6})[ \t]+(.*?)[ \t]*$/

/** Matches a closing sequence of hashes at the end of an ATX heading (e.g. `## Title ##`). */
const ATX_CLOSING = /[ \t]+#+[ \t]*$/

/** Matches the opening (or closing) line of a fenced code block, optionally indented up to three spaces. */
const FENCE = /^ {0,3}(`{3,}|~{3,})[ \t]*.*$/

/** Matches a bare fence line with nothing but the fence characters, used to detect the closing fence. */
const FENCE_CLOSE = /^ {0,3}(`{3,}|~{3,})[ \t]*$/

/** Matches an indented code block line (four spaces or a leading tab). */
const INDENTED_CODE = /^(?: {4}|\t)/

/** Matches a setext underline made entirely of `=` (level 1) characters. */
const SETEXT_H1 = /^ {0,3}=+[ \t]*$/

/** Matches a setext underline made entirely of `-` (level 2) characters. */
const SETEXT_H2 = /^ {0,3}-+[ \t]*$/

/**
 * Removes inline markdown formatting from a heading, keeping only the readable text.
 *
 * Handles images (keeping alt text), links (keeping link text), bold, strikethrough,
 * italic, inline code, and raw HTML tags.
 */
const stripInlineFormatting = (text: string): string =>
  text
    // Images: ![alt](url) -> alt (handled before links because of the shared bracket syntax)
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
    // Links: [text](url) -> text
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    // Bold: **text** or __text__ -> text (handled before italic to consume the double markers first)
    .replace(/(\*\*|__)(.*?)\1/g, '$2')
    // Strikethrough: ~~text~~ -> text
    .replace(/~~(.*?)~~/g, '$1')
    // Italic: *text* or _text_ -> text
    .replace(/(\*|_)(.*?)\1/g, '$2')
    // Inline code: `code` -> code
    .replace(/`+([^`]*)`+/g, '$1')
    // Raw HTML tags: <span> -> (removed)
    .replace(/<[^>]+>/g, '')
    .trim()

/**
 * Parses a markdown string and extracts every heading, both ATX (`# Heading`) and
 * setext (underlined with `=` or `-`) styles.
 *
 * Content inside fenced code blocks (triple backticks or tildes) and indented code
 * blocks (four-space indent) is ignored. Inline formatting is stripped from the
 * returned values, and Windows (CRLF) line endings are handled transparently.
 *
 * @param markdown - The markdown string to parse
 * @returns An array of headings, each with a numeric `depth` (1-6) and a plain-text `value`
 *
 * @example
 * getMarkdownHeadings('# Getting Started\n## Installation')
 * // [
 * //   { depth: 1, value: 'Getting Started' },
 * //   { depth: 2, value: 'Installation' },
 * // ]
 */
export const getMarkdownHeadings = (markdown: string): MarkdownHeading[] => {
  if (!markdown) {
    return []
  }

  // Normalize Windows (\r\n) and old Mac (\r) line endings before splitting.
  const lines = markdown.replace(/\r\n?/g, '\n').split('\n')
  const headings: MarkdownHeading[] = []

  let inFence = false
  let fenceChar = ''

  for (let index = 0; index < lines.length; index++) {
    const line = lines[index] ?? ''

    // Inside a fenced code block: only look for the matching closing fence.
    if (inFence) {
      const close = line.match(FENCE_CLOSE)
      if (close && close[1][0] === fenceChar) {
        inFence = false
      }
      continue
    }

    // A fence opener starts a code block whose contents must be ignored.
    const fence = line.match(FENCE)
    if (fence) {
      inFence = true
      fenceChar = fence[1][0]
      continue
    }

    // Indented code blocks are not headings.
    if (INDENTED_CODE.test(line)) {
      continue
    }

    // ATX heading: leading hashes at the very start of the line.
    const atx = line.match(ATX_HEADING)
    if (atx) {
      const value = stripInlineFormatting(atx[2].replace(ATX_CLOSING, ''))
      if (value) {
        headings.push({ depth: atx[1].length, value })
      }
      continue
    }

    // Setext heading: a line of text immediately followed by an underline row.
    if (line.trim() !== '') {
      const next = lines[index + 1]

      if (next !== undefined && SETEXT_H1.test(next)) {
        const value = stripInlineFormatting(line.trim())
        if (value) {
          headings.push({ depth: 1, value })
        }
        index++
        continue
      }

      if (next !== undefined && SETEXT_H2.test(next)) {
        const value = stripInlineFormatting(line.trim())
        if (value) {
          headings.push({ depth: 2, value })
        }
        index++
        continue
      }
    }
  }

  return headings
}
